mapper.select:
SELECT SHIFT_DATE,DKEY,TOOLID,CHAMBERID,MODULE,LIFETIME,EXPIRETIME,JOBGROUPID ,JOBSPECID,EQP_G,REMAIN_RDS,CLAIMUSER,WIP,WIP_CLOSE_1D ,EXPIRE_REASON,F_COMMENT FROM( SELECT A.* FROM( SELECT A.SHIFT_DATE,A.DKEY,A.TOOLID,A.CHAMBERID,A.MODULE,A.LIFETIME ,A.EXPIRETIME,A.JOBGROUPID,A.JOBSPECID,A.EQP_G,A.REMAIN_RDS,A.CLAIMUSER,A.WIP,A.WIP_CLOSE_1D ,B.WEEK_SEQ,B.SHIFT_MONTH ,C.EXPIRE_REASON,C.F_COMMENT FROM A1_MFG.RDS_EXPIRE_DETAIL A LEFT JOIN( SELECT DISTINCT SHIFT_MONTH,WEEK_SEQ,SHIFT_DATE FROM A3MFGYW1.CLIP_CALENDAR )B ON A.SHIFT_DATE = B.SHIFT_DATE LEFT JOIN ( SELECT DISTINCT FAB,MODULE,TOOLID,JOBGROUPID,EXPIRE_TIME,EXPIRE_REASON,F_COMMENT FROM A1_MFG.RDS_OVERTIME_REASON )C ON A.FAB = C.FAB AND A.MODULE = C.MODULE AND A.TOOLID = C.TOOLID AND A.JOBGROUPID = C.JOBGROUPID AND TO_CHAR(A.EXPIRETIME,'YYYY-MM-DD HH24:MI:SS') = C.EXPIRE_TIME WHERE A.FAB = #{fab}
AND A.MODULE = #{module}
AND A.SHIFT_DATE = #{date}
AND B.WEEK_SEQ = #{date}
AND B.SHIFT_MONTH = #{date}
AND (NVL(WIP_CLOSE_1D,0) > 0 OR A.MODULE ='METRO')
)A) ORDER BY DECODE(MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'METRO',6,7),TOOLID,JOBGROUPID,REMAIN_RDS

SELECT SHIFT_DATE,DKEY,TOOLID,CHAMBERID,MODULE,LIFETIME,EXPIRETIME,JOBGROUPID,JOBSPECID,EQP_G,REMAIN_RDS,CLAIMUSER,WIP,WIP_CLOSE_1D ,EXPIRE_REASON,F_COMMENT,CREATE_TIME FROM( SELECT A.* FROM( SELECT CASE WHEN A.DATE_TIME = '00' OR A.DATE_TIME = '06' THEN TO_CHAR(TO_DATE(A.SHIFT_DATE,'YYYYMMDD')+1,'YYYYMMDD') ELSE A.SHIFT_DATE END ||' '||A.DATE_TIME||':00' SHIFT_DATE,A.DKEY,A.TOOLID,A.CHAMBERID,A.MODULE,A.LIFETIME ,A.EXPIRETIME,A.JOBGROUPID,A.JOBSPECID,A.EQP_G,A.REMAIN_RDS,A.CLAIMUSER,A.WIP,A.WIP_CLOSE_1D ,B.SHOP_WEEK,B.SHOP_MONTH ,C.EXPIRE_REASON,C.F_COMMENT ,A.CREATE_TIME FROM A1_MFG.RDS_HIT_RATIO_DETAIL A LEFT JOIN( SELECT DISTINCT SHOP_MONTH,SHOP_WEEK,SHIFT_DATE FROM ODS.WP_CALENDAR@A1PDW )B ON A.SHIFT_DATE = B.SHIFT_DATE LEFT JOIN ( SELECT DISTINCT FAB,MODULE,TOOLID,JOBGROUPID,EXPIRE_TIME,EXPIRE_REASON,F_COMMENT FROM A1_MFG.RDS_OVERTIME_REASON )C ON A.FAB = C.FAB AND A.MODULE = C.MODULE AND A.TOOLID = C.TOOLID AND A.JOBGROUPID = C.JOBGROUPID AND TO_CHAR(A.EXPIRETIME,'YYYY-MM-DD HH24:MI:SS') = C.EXPIRE_TIME WHERE A.FAB =#{fab} AND CASE WHEN A.DATE_TIME = '00' OR A.DATE_TIME = '06' THEN TO_CHAR(TO_DATE(A.SHIFT_DATE,'YYYYMMDD')+1,'YYYYMMDD') ELSE A.SHIFT_DATE END ||' '|| A.DATE_TIME||':00' = #{shiftDate}
AND A.MODULE = #{module}
)A) ORDER BY DECODE(MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'METRO',6,7),TOOLID,JOBGROUPID,REMAIN_RDS

SELECT SHIFT_DATE,COUNT(1)JOB_COUNT ,CASE WHEN SHIFT_DATE = TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') THEN 1 ELSE 0 END TODAY_FLAG FROM( SELECT A.SHIFT_DATE,A.MONTIOR_PLAN_NAME,A.MODULE,A.TOOLID ,A.SUBNAME ,A.JOB_SPEC_GROUP_ID , ROW_NUMBER()OVER(PARTITION BY TOOLID,SUBNAME,JOB_SPEC_GROUP_ID,SHIFT_DATE ORDER BY STARTTIME DESC)JOB_FLAG FROM A1_MFG.OCS_MONITOR_PLAN_SETTING_DAILY A WHERE SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-7,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24+30,'YYYYMMDD')
AND LENGTH(TOOLID) = 5
AND LENGTH(TOOLID) = 6
AND MODULE = #{module}
)GROUP BY SHIFT_DATE ORDER BY SHIFT_DATE

SELECT DISTINCT SHIFT_DATE, DKEY,TOOLID,CHAMBERID,MODULE,LIFETIME,JOBGROUPID,CLAIMUSER,LASTSTAMPTIME,PRE_EXPIRETIME
FROM A1_MFG.RDS_MANUAL_DETAIL
WHERE SHIFT_DATE = #{shiftDate} AND MODULE = #{module} AND FAB = #{fab}

delete from A1_MFG.COMMENT_SUMMARY
where FUNCTION_NAME = 'RDS_EQPG_BACKUP_JOBGROUP'
AND KEY1=#{eqpId} and KEY2 = #{chamberId}
AND KEY3=#{eqpg} and KEY4 = #{jobGroupId}
